const pageCount = $json.body.PageCount;   // from PDF Info
const batchSize = 20;

const ranges = [];
for (let i = 1; i <= pageCount; i += batchSize) {
  const start = i;
  const end = Math.min(i + batchSize - 1, pageCount);
  ranges.push(start === end ? `${start}` : `${start}-${end}`);
}

return ranges.map(r => ({ json: { range: r } })); // <- emit one item per range

// Mode: Run Once for All Items
const summaries = items.map(i => i.json.output || i.json); // adjust if your field name differs
const withRanges = items.map(i => {
  const r = i.json.range ? `[Pages ${i.json.range}] ` : '';
  return r + (i.json.output ?? i.json);
});

return [
  {
    json: {
      // choose one:
      combined: withRanges.join('\n\n---\n\n')  // keeps page labels if available
      // combined: summaries.join('\n\n---\n\n') // plain summaries
    }
  }
];

// Clean Text -> chunk -> add book_slug from "Get Info about file"

// ===== 0) Build book_slug =====
const INFO_NODE_NAME = "Get Info about file";
const USER_INFO_NODE = "User Information";

function slugify(s) {
  return String(s || "book")
    .normalize("NFKD")               // handle accents safely
    .replace(/\p{Diacritic}/gu, "")  // strip diacritics
    .replace(/\.[^/.]+$/, "")        // drop extension
    .toLowerCase()
    .replace(/[_\s]+/g, "-")         // spaces/underscores -> -
    .replace(/[^a-z0-9-]/g, "")      // strip non-url chars
    .replace(/-+/g, "-")             // collapse --
    .replace(/^-|-$/g, "");          // trim -
}

// Safely read the PDF info node
let infoItem = null;
try {
  const arr = $items(INFO_NODE_NAME, 0, 0) || [];
  infoItem = arr[0] || null;
} catch {}
const infoJson = infoItem?.json ?? {};
const infoBin  = infoItem?.binary ?? {};

// Title (often empty)
const titleFromInfo = infoJson?.body?.Title || infoJson?.Title || "";

// Read file_name from User Information
const fileNameFromUser = $node[USER_INFO_NODE]?.json?.file_name || "";

// Other fallbacks just in case
const fileNameFromInfo =
  infoJson?.fileName ||
  infoBin?.data?.fileName ||
  infoBin?.file?.fileName ||
  "";
const fileNameFromHere =
  $json?.fileName ||
  $binary?.data?.fileName ||
  "";

// Choose best: Title > User file_name > other fallbacks
const chosenName =
  (titleFromInfo && titleFromInfo.trim()) ||
  fileNameFromUser ||
  fileNameFromInfo ||
  fileNameFromHere ||
  "book.pdf";

const book_slug = slugify(chosenName);

// ===== 1) Get source text (use merged_text from previous step) =====
let raw =
  $json?.merged_text ||   // comes from "Text and Final Summary" step
  $json?.text ||
  $json?.output ||
  "";
if (typeof raw !== "string") return [];

// ===== 1a) Safe meta scrub (tail-only, very specific AI/meta phrases) =====
function stripMetaLines(rawText) {
  const LINES = rawText.split(/\r?\n/);
  const tailStart = Math.max(0, LINES.length - 150); // scan only the tail
  const head = LINES.slice(0, tailStart);
  const tail = LINES.slice(tailStart);

  const META_SUBSTRINGS = [
    "I'm unable to provide a summary for",
    "I'm unable to include any sections from",
    "I can't assist with that",
    "I cannot assist with that",
    "I am not able to",
    "Please provide a section from the main text",
    "Please provide a different part of the text",
    "Could you provide a different part",
    "This section typically contains metadata",
    "bibliographic or index notes",
    "rather than substantive content",
    "from the book itself",
    "as an AI",
    "for summarization",
    "section from the main text",
    "provide a different part of the text",
    "Notes” as this section typically contains metadata",
  ];

  const HARD_FILTERS = [
    /^```+$/,                 // code fences
    /^\s*Output:?$/i,
    /^\s*Final Summary\s*$/i, // accidental duplicate heading
  ];

  const tailClean = tail.filter(line => {
    const trimmed = line.trim();
    if (!trimmed) return false;

    if (HARD_FILTERS.some(rx => rx.test(trimmed))) return false;

    const hasMeta = META_SUBSTRINGS.some(s => trimmed.includes(s));
    return !hasMeta;
  });

  return [...head, ...tailClean].join("\n");
}
raw = stripMetaLines(raw);

// ===== 2) Cleanup =====
let text = raw
  .replace(/```+/g, "")            // drop stray code fences
  .replace(/\*\*/g, "")
  .replace(/\*/g, "")
  .replace(/\\n\\n/g, "\n\n")      // handle escaped newlines
  .replace(/\\n/g, "\n")
  .replace(/\r/g, "")
  .replace(/[ \t]+/g, " ")
  .replace(/\n[ \t]+/g, "\n")
  .trim();
if (!text) return [];

// ===== 3) Chunking =====
const MAX = 2800;  // hard ceiling per chunk
const MIN = 2000;  // prefer at least this size

const paras = text.split(/\n{2,}/).map(p => p.trim()).filter(Boolean);

const chunks = [];
let cur = "";

function pushChunk() {
  if (!cur.trim()) return;
  chunks.push(cur.trim());
  cur = "";
}

for (const p of paras) {
  if ((cur + "\n\n" + p).length <= MAX) {
    cur = cur ? cur + "\n\n" + p : p;
  } else {
    if (cur.length >= MIN) {
      pushChunk();
      cur = p;
    } else {
      // sentence-aware split (handles quotes/parentheses reasonably)
      const sents = p.match(/[^.!?…]+[.!?…]+"?'?\)?\s*/g) || [p];
      for (const s0 of sents) {
        const s = s0.trim();
        if ((cur + " " + s).length <= MAX) {
          cur = cur ? cur + " " + s : s;
        } else {
          pushChunk();
          cur = s;
        }
      }
    }
  }
}
pushChunk();

// Fallback: if a single paragraph has no punctuation and still > MAX, hard-slice
for (let i = 0; i < chunks.length; i++) {
  if (chunks[i].length > MAX + 200) {
    const hard = [];
    let t = chunks[i];
    while (t.length) {
      hard.push(t.slice(0, MAX));
      t = t.slice(MAX);
    }
    chunks.splice(i, 1, ...hard);
    i += hard.length - 1;
  }
}

// ===== 4) Per-chunk cleanup for TTS + include book_slug =====
const itemsOut = chunks.map((t, i) => {
  let tt = t;
  tt = tt.replace(/^\s*##\s+/gm, "");
  tt = tt.replace(/^\s*(Introduction|Conclusion)\b/gm, "$1:");
  tt = tt.replace(/[“”]/g, '"').replace(/[‘’]/g, "'").replace(/\s*—\s*/g, " — ");
  tt = tt.replace(/[ \t]+/g, " ").replace(/\n{3,}/g, "\n\n").trim();
  if (!/[.!?]"?\s*$/.test(tt)) tt += ".";
  tt += "\n\n";
  return { json: { index: i, text: tt, book_slug } };
});

return itemsOut;

// Run Once For All Items OR For Each Item (both fine)
return items.map((item, i) => {
  const j = item.json || {};

  // Pick only what we need downstream
  const public_url = j.public_url ?? j.url ?? null;
  const index      = j.index ?? i;           // fallback to order
  const book_slug  = j.book_slug ?? null;

  // Optionally pass storage path metadata if you use it later
  const key        = j.key ?? j.Key ?? j.objectPath ?? null;

  return {
    json: {
      public_url,
      index,
      book_slug,
      key
    }
    // no binary, no other metadata
  };
});

// Expect one item whose json has { data: [ { public_url, index?, key?, book_slug? }, ... ], book_slug? }
// Do NOT call $input.all() here.

const USER_INFO_NODE = "User Information";
const CLEAN_NODE     = "Clean Text";

function slugify(s) {
  return String(s || "book")
    .replace(/\.[^/.]+$/, "")
    .toLowerCase()
    .replace(/[_\s]+/g, "-")
    .replace(/[^a-z0-9-]/g, "")
    .replace(/-+/g, "-")
    .replace(/^-|-$/g, "");
}

const rows = Array.isArray($json.data) ? $json.data : [];
if (!rows.length) {
  const uf = $node[USER_INFO_NODE]?.json?.file_name || "";
  return [{ json: { book_slug: $json.book_slug || (uf && slugify(uf)) || "book", urls: [], listText: "" } }];
}

// Prefer book_slug from several sources; fall back to filename or parse from URL.
function pickBookSlug() {
  if ($json.book_slug) return String($json.book_slug);

  const fromRow = rows.find(r => r.book_slug)?.book_slug;
  if (fromRow) return String(fromRow);

  const fromClean = $node[CLEAN_NODE]?.json?.book_slug;
  if (fromClean) return String(fromClean);

  // Parse from first URL: /object/(public/)?(audio_books|Books)/<slug>/
  const firstUrl = String(rows[0]?.public_url || rows[0]?.url || "").replace(/[\r\n]+/g, "");
  const m = firstUrl.match(/\/object\/(?:public\/)?(?:audio_books|Books)\/([^/]+)\//i);
  if (m) return m[1];

  const fileName = $node[USER_INFO_NODE]?.json?.file_name || "";
  if (fileName) return slugify(fileName);

  const firstKey = rows[0]?.key ?? rows[0]?.Key ?? "";
  if (firstKey) {
    const parts = String(firstKey).split("/");
    if (parts.length > 1 && parts[1]) return String(parts[1]);
  }
  return "book";
}
const book_slug = pickBookSlug();

// Sort parts
function partIndex(row) {
  if (row.index != null) return Number(row.index);
  const u = String(row.public_url || row.url || "");
  let m = u.match(/part_(\d+)\.mp3/i);
  if (!m) m = String(row.key || row.Key || "").match(/part_(\d+)\.mp3/i);
  return m ? Number(m[1]) : 0;
}
rows.sort((a, b) => partIndex(a) - partIndex(b));

// Clean URLs (strip newlines & accidental //) and build concat list
const urls = rows
  .map(r => String(r.public_url || r.url || ""))
  .map(u => u.replace(/[\r\n]+/g, "").replace(/([^:]\/)\/+/g, "$1").trim())
  .filter(Boolean);

const listText = urls.map(u => `file '${u}'`).join("\n");

return [{ json: { book_slug, urls, listText } }];

