// Pick the result that contains storage info
const r = ($json.results?.store_to_supabase?.[0])
       || ($json.results?.mp3?.[0])
       || null;

const bucket = r?.bucket || 'Books'; // still private bucket

// Collect fields (prefer those Transloadit echoed back)
const fields = $json.fields ?? {};
const bookSlug = fields.book_slug ?? $json.book_slug ?? 'book';
const userId   = fields.user_id   ?? $json.user_id   ?? null;
const uploadId = fields.upload_id ?? $json.upload_id ?? null;

// Prefer Transloadit's own path when present
let objectPath = r?.path;

// Fallback: construct path exactly like your Transloadit template
if (!objectPath) {
  if (userId && uploadId) {
    // New structure with per-user & per-upload
    objectPath = `${bookSlug}/${userId}/${uploadId}/${bookSlug}.mp3`;
  } else {
    // Old structure (pre-change) for backwards compatibility
    objectPath = `${bookSlug}/${bookSlug}.mp3`;
  }
}

// Normalize any accidental leading slashes from the response
objectPath = String(objectPath).replace(/^\/+/, '');

// Return compact metadata for downstream (signing URL, DB insert, etc.)
return [{
  book_slug: bookSlug,
  user_id: userId,
  upload_id: uploadId,
  bucket,
  objectPath
}];

// Inputs from previous node:
const bucket   = $json.bucket || 'Books';
let objectPath = String($json.objectPath || '').replace(/^\/+/, '');

// URL-safe encode each segment (handles spaces, parentheses, etc.)
const safePath = objectPath
  .split('/')
  .map(encodeURIComponent)
  .join('/');

const PUBLIC_BASE =
  'https://YOUR_PROJECT.supabase.co/storage/v1/object/public';

// Final NEVER-expiring public URL
const url = `${PUBLIC_BASE}/${encodeURIComponent(bucket)}/${safePath}`;

return [{
  bucket,
  objectPath,
  url,                 // ← store this in DB
  public: true,
  expiresIn: null,     // no expiry
  expiresAt: null,     // no expiry
  user_id:   $json.user_id   ?? null,
  upload_id: $json.upload_id ?? null,
  book_slug: $json.book_slug ?? null
}];

// Names of upstream nodes (change only if your node labels differ)
const COMBINE_NODE = "Combine";
const FINAL_NODE   = "Final Summary";

// Get combined text (unchanged)
const combined =
  ($node[COMBINE_NODE]?.json?.combined ?? "").toString();

// Get model’s Final Summary output
let finalSummary =
  ($node[FINAL_NODE]?.json?.output ?? $json?.output ?? "").toString().trim();

// Safety: if the model accidentally returned extra stuff, keep only the
// section that begins with the heading “Final Summary”
const m = finalSummary.match(/(^|\n)\s*#{0,3}\s*Final Summary[\s\S]*$/i);
if (m) finalSummary = m[0].trim();

// Build merged text
const merged = combined
  + (finalSummary ? `\n\n${finalSummary}\n` : "");

// Emit
return [{ json: { merged_text: merged } }];
